        const doorOffset = (SHAFT_WIDTH / 2 - 0.5) * (1 - easedProgress);
        elevatorCar.leftDoor.position.x = -doorWidth / 2 - 0.05 + doorOffset;
        elevatorCar.rightDoor.position.x = doorWidth / 2 + 0.05 - doorOffset;

