    const pillarPositions = [
        { x: -(SHAFT_WIDTH - 0.2) / 2, z: -(SHAFT_DEPTH - 0.2) / 2 },
        { x: (SHAFT_WIDTH - 0.2) / 2, z: -(SHAFT_DEPTH - 0.2) / 2 },
        { x: -(SHAFT_WIDTH - 0.2) / 2, z: (SHAFT_DEPTH - 0.2) / 2 },
        { x: (SHAFT_WIDTH - 0.2) / 2, z: (SHAFT_DEPTH - 0.2) / 2 }
    ];

    pillarPositions.forEach(pos => {
        const pillar = new THREE.Mesh(pillarGeo, frameMaterial);
        pillar.position.set(pos.x, (FLOOR_HEIGHT - 0.3) / 2, pos.z);
