                                }
                            }, 1000);
                        });
                    });
                });
            });
            break;

        case 'idle':
            // Wait for next move to be scheduled
            break;
    }
}

function pickRandomPerson() {
    if (people.length === 0) return;

    currentPersonIndex = Math.floor(Math.random() * people.length);
